"""Actual render comparison plus explicitly labelled non-RGB diagnostics."""
import json,ast,hashlib
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw,ImageFont
from geometry111 import H,read,packet_list,plane
def font(n):return ImageFont.truetype('C:/Windows/Fonts/malgun.ttf',n)
COL=np.array([[24,33,44],[63,202,235],[250,234,188],[184,119,251],[255,85,149]],np.uint8)
def preview(p):
    meta,a=plane(p/'H-product77-final.plane');a=np.flipud(a)[:,:,:3];clipped=int(np.count_nonzero((a<0)|(a>1)));q=np.clip(a,0,1);rgb=np.rint(np.where(q<=.0031308,q*12.92,1.055*q**(1/2.4)-.055)*255).astype(np.uint8);return Image.fromarray(rgb),{'sourceId':meta['sourceId'],'encoding':'linearRT -> sRGB8 preview','clippedChannels':clipped,'rawMax':float(a.max())}
def main():
    state,paths=packet_list();index={read(p/'RAW_MANIFEST.json')['frameIndex']:p for p in paths};forms={v['frame']:v for v in read(H/'FORM111.json')};captures=[];board=Image.new('RGB',(1250,1000),'#101923');d=ImageDraw.Draw(board);d.text((22,16),'Close75: actual77 render + source/footprint diagnosis111',font=font(27),fill='white');d.text((22,60),'The character images are ACTUAL GPU77 captures. Role maps and sample masks are diagnostics, not candidate final RGB.',font=font(16),fill='#bdd5e5')
    for n,(frame,label)in enumerate([(122,'Hair ON'),(125,'Hair OFF'),(128,'Hair restored')]):
        x=22+n*410;im,meta=preview(index[frame]);im.save(H/f'ACTUAL111-frame{frame}.png');captures.append(meta);d.text((x,100),f'New111 F{frame}: {label}',font=font(21),fill='white');board.paste(im,(x,145));board.paste(im.resize((im.width*3,im.height*3),Image.Resampling.NEAREST),(x+95,145))
        a=read(H/f'ANALYSIS111-frame{frame}.json');merged=np.zeros_like(np.array(a['eyes'][0]['variants'][1]['labels'][0]));chosen={e['owner']:e['selectedIndices'][0]for e in forms[frame]['eyes']}
        for e in a['eyes']:
            q=np.array(e['variants'][1]['labels'][chosen[e['owner']]]);assert not np.any((merged>0)&(q>0));merged=np.maximum(merged,q)
        labelImage=Image.fromarray(COL[merged]);labelImage.save(H/f'CANONICAL111-frame{frame}.png');board.paste(labelImage.resize((324,144),Image.Resampling.NEAREST),(x,440));d.text((x,412),'Canonical BEFORE external hair (same labels)',font=font(16),fill='#d7e5ef')
        ablation=read(H/f'LAYER_ABLATION111-frame{frame}.json');e=ablation['eyes'][1];selected=chosen[2]
        d.text((x,610),'Eye2 white cell x3/y5: exact destination S4',font=font(16),fill='#d7e5ef')
        for k,(policy,title)in enumerate([('native','Original gates'),('geometry-only','Geometry only'),('feature-canvas','Canvas hypothesis')]):
            v=next(v for v in e['policies']if v['policy']==policy);cell=next(c for c in v['exposure'][selected]if c['part']==2);tile=np.zeros((4,4,3),np.uint8);lo,hi=cell['visibleCarrierFractionBounds']
            for sample in cell['samples']:
                y,xx=sample['fine'];l,u=sample['visibleBounds'];tile[y,xx]=COL[2]if l>=1 else COL[4]if u>l else [255,172,72]if l>0 else COL[0]
            board.paste(Image.fromarray(tile).resize((88,88),Image.Resampling.NEAREST),(x+k*132,657));d.text((x+k*132,750),title,font=font(13),fill='white');d.text((x+k*132,776),f'{lo:.3g}..{hi:.3g} /16',font=font(17),fill='#eee5bb')
    d.text((22,850),'Confirmed: source white survives; area-first allocation drops it. Source pigment alpha is not destination carrier geometry.',font=font(18),fill='#a8dded');d.text((22,881),'Actual source/geometry-only carrier runs: 12 +12 frames. New GPU allocator / canvas policy / final palette remain unimplemented.',font=font(17),fill='#ffb1a7');d.text((22,912),'Canvas mapping is a limited SOURCE-bank hypothesis, not a true-lid annotation. It retains real external hair occlusion.',font=font(17),fill='#ffb1a7');d.text((22,946),'Cream=clear sample, dark=blocked, orange=partial, pink=uncertain. Actual frame gaps are recorded; no temporal-stability claim.',font=font(15),fill='#bdd5e5');board.save(H/'WHITE_CARRIER111.png')
    gpu=read(H/'GPU_CARRIER111.json');post=read(H/'gpu-carrier/CURRENT_POST111G.json');st1=read(sorted((H/'capture').glob('STATE111-*.json'))[-1]);st2=read(sorted((H/'gpu-carrier').glob('STATE111G-*.json'))[-1]);filtered=lambda s,k:sorted((v['path'],v['type'])for v in s[k]if v['path'].startswith(('Assets/','ProjectSettings/')))
    assert filtered(st1,'beforeDirty')==filtered(st1,'afterDirty')==filtered(st2,'beforeDirty')==filtered(st2,'afterDirty')
    status={'actualPlayEntries':2,'actualCapturedFrames':24,'runtimeGeometryOnlyCarrierFix':'NativeCarrier111.shader on owned NativeGeometryCarrier111 materials in ForwardGeometry111 graph; source bank pass and default77 unchanged','runtime2_2AllocatorApplied':False,'runtimeCanvasHypothesisApplied':False,'actualGPUQueryChecks':1728,'CPUvsGPUIntervalsMaxDifference':0,'CPUvsGPUReprojectionResidualPixelsMax':max(v['GPUQueryValidation']['maxCanonicalProjectionResidualPixels']for v in gpu['frames']),'sourceAllocationAndFinalOcclusionSeparated':True,'hairON_OFF_restoredCanonicalLabelSetsEqual':True,'remaining':['Eye whole-form/pixel-carrier binding is not defined by nearest-eye tags on generic face skin.','Source-bank canvas hypothesis improves small-white exposure with hair OFF, but still clips/changes other sample support. Rotation/lid semantics and GPU selection/composition remain unverified.','Complete finite palette/outline path remains separate and unfinished.'],'latestEditor':{'utc':post['utc'],'playing':post['playing'],'compiling':post['compiling'],'updating':post['updating'],'dirty':len(post['dirty']),'scene':post['scenes'],'inputNativeId':post['input']['nativeId']},'restore':{'dirty31Preserved':True,'originalNativeContentMatches':46,'nativeCompared':47,'unavailable':'UnityEditor.AssetImporter wrapper only; PlayerSettings JSON matched','inputSameAliveObjectJSONAndDevices':True,'optionsTimePipelineBackgroundGlobalsRestored':True,'ownCarrierResourcesDisposed':True,'RTCountBeforeAfter':[30,30]},'memory':[{'before':s['beforeMemory'],'after':s['afterMemory'],'allocatedDeltaBytes':s['afterMemory']['allocated']-s['beforeMemory']['allocated'],'API':'Unity Profiler.GetTotalAllocatedMemoryLong; not physical WS; no leak/complete memory-restoration claim'}for s in[st1,st2]],'serverApprovalDenied':False,'runningUnityCommand':False,'product77DefaultChanged':False,'previewEncoding':captures}
    (H/'STATUS111.json').write_text(json.dumps(status,indent=2,ensure_ascii=False)+'\n');(H/'CODE_INDEX111.json').write_text(json.dumps({str(p.relative_to(H)):[{'function':n.name,'line':n.lineno}for n in ast.parse(p.read_text(encoding='utf8')).body if isinstance(n,(ast.FunctionDef,ast.ClassDef))]for p in H.glob('*.py')},indent=2)+'\n')
    contract={'implementedLive':['same-frame8x source rest/UV/bank RGB + IDs verified without nearest-key guessing','direct evaluated world/rest/indices/material + exact current transforms','geometry-only native carrier shader and real GPU face visibility, original occluder alpha retained','normal Play12state capture/restore repeated for one definite geometry-alpha fix'],'notImplementedLive':['2.2 typed upper-boundary/component allocator','registered feature-canvas ownership hypothesis','final finite RGB palette and outline lookup'],'staticCacheInputs':['original feature source keys/RGBA family','part/component adjacency and native pigment path UV/barycentric binding','registration projections and carrier ownership policy','model/topology/UV/bank/texture-generation signature'],'perFrameInputs':['view/renderer scope, source frame/serial, continuous anchor and current deformed vertices','source support intervals and source feature IDs BEFORE external hair','destination footprint per-sample carrier/world/UV/depth + actual occluder alpha','original lighting g/Q and palette indices in independent channels'],'ownership':['One explicit owner per renderer/view/generation, shared immutable source cache only.','Own buffers/RT/material/shader clones disposed on failure or scope change; borrowed meshes/textures/buffers never disposed.','Invalidate on model/topology/UV/source-feature or bank content edits; palette spacing must not change shape IDs.','SourceGeometry111 streams existing evaluated CPU arrays; no per-frame GPU->CPU feedback may be introduced in product.'],'runtimeCostLimit':'Current exact solver is offline subset enumeration, not a real-time implementation. Observed<=9 iris/12 white source candidates; full search or a bounded exact DP/GPU reduction still requires implementation/profiling. GPU time was not measured or substituted by CPU time.','nextNarrowQuestion':'Which source-local deformation/carrier map covers the entire cached stylized eye support while current lid/Close controls internal shape, generic skin is canvas, and external face/hair still occlude? Current nearest-eye face tags and a single depth cannot encode that policy. This is a missing representation/ownership contract, not a proven information-theoretic impossibility or a request for fixed eye counts.'}
    (H/'RUNTIME_CONTRACT111.json').write_text(json.dumps(contract,indent=2)+'\n')
    html='''<!doctype html><meta charset="utf-8"><title>눈 source·carrier 검증111</title><style>body{background:#101923;color:#dce8f2;font:17px/1.7 system-ui;max-width:1280px;margin:25px auto;padding:0 20px}a{color:#7cdbec}img{max-width:100%;image-rendering:pixelated}strong{color:#ffb3aa}</style><h1>작은 흰자: source → 배정 → carrier → 실제 가림</h1><p>2회 정상 Play에서 실제12+12프레임을 새 sourceId로 기록하고 종료·복원을 확인했습니다. 이전107의 추정 기하를 섞지 않았습니다. 실제8× source 좌표·색, 직접 평가된 정점/UV/삼각형/재질과 같은 프레임의 카메라·등록행렬, GPU face query 및 실제 머리 S4를 보존했습니다. CPU ray와 GPU의 표본1728개는 차이0이며, 일반적인 셰이더 동등성 보장은 아닙니다.</p><p>Close75 흰자는 가림으로 완전히 사라지지 않았습니다. 새 프레임에서도 확실한 가시 source0.34375셀이 남으며 원래 분리된 흰자 성분 중 하나에 속합니다. 면적 우선 배정은 EyeUnion1.125를1셀로 표현하는 오차를 먼저 줄여 그 성분을 버렸습니다. source 성분 손실을 먼저 비교하는 후보는 고정 최소 셀 수 없이 그것을 남깁니다. 하나의 출력 셀이 여러 source 성분을 대표할 수도 있는 별도 반례도 검사했습니다.</p><p><strong>배정만 되돌려도 완성은 아닙니다.</strong> 원래 위치의 흰자 carrier는 네이티브 조건에서16표본 중1~2개만 보입니다. 그 뒤에는 원래 색소 알파를 목적지 기하 범위로 다시 사용한 문제와 피부/눈꺼풀 소유권 문제가 있습니다. 색소 알파 분리용 새 <code>NativeCarrier111.shader</code>는 소유한 임시 재질에만 연결해 실제 GPU12상태를 검증했습니다. 원본 색 공급·실제 occluder alpha·제품77 기본값은 유지했습니다. C# Assets import/domain reload도 없었습니다.</p><img src="WHITE_CARRIER111.png"><p>인물 그림은 새로 저장한 실제77 GPU 렌더입니다. role map 및 표본 마스크는 진단이며 후보의 최종 RGB가 아닙니다. 머리ON/OFF/복원에서 가림 전 canonical 배치 집합은 동일합니다. 원본 bank 범위만 특징 바탕으로 묶는 제한적 가설에서는 머리OFF 흰자가2/16→12/16으로 늘지만 ON에서는 실제 머리 가림 때문에3/16이 남습니다. 이를 항상 보존해야 할 흰자 픽셀이라고 강제하지 않았습니다.</p><p><strong>미채택:</strong> 바탕 연결 가설과 전체2.2 배정기는 GPU에 아직 적용하지 않았습니다. 현재 face의 eye owner는 모든 얼굴 정점을 가까운 눈으로 나눈 값이어서 실제 눈꺼풀 표지가 아닙니다. source bank 범위도 원래 제작자의 실제 안검 경계라고 단정할 수 없습니다. 부분Close의 홍채/흰자 전체 support를 어떤 변형 carrier에 공동 배치할지, 실제 lid와 generic skin을 어떻게 구분할지가 남아 있습니다. 모든 피부를 무시하거나 거의 가려진 잔여 표본을 성공으로 세지 않았습니다. 원천적 불가능성이 증명된 결과도 아닙니다. 유한 팔레트·외곽선은 별도 미완입니다.</p><p>종료 뒤 Edit/컴파일 아님/dirty31/입력 설정 동일 객체·JSON·장치 보존. 직렬화47개 중46개 동일,1개 AssetImporter 래퍼는 조회 불가이며 PlayerSettings 본문은 동일했습니다. 두 실행 모두 RT30→30, 소유 자원 해제·global/옵션/시간/pipeline 복원을 확인했습니다. Unity CPU할당 카운터는 각 실행에서 약35.49MiB/25.81MiB 늘었고 OS 물리RAM이나 누수 확정을 뜻하지 않습니다. 새 샘플은 frame gap이 있으므로 시간 안정성 완성을 주장하지 않습니다.</p><p><a href="STATUS111.json">실행·복원·한계</a> / <a href="CHECK111.json">오라클/변환 검사</a> / <a href="GPU_CARRIER111.json">실제GPU carrier 수정</a> / <a href="RUNTIME_CONTRACT111.json">런타임 입력·수명·남은 연결</a> / <a href="CODE_INDEX111.json">함수 위치</a> / <a href="CAPTURE_INDEX111.json">새24개 source 입력</a>. 코드·인계·선택 커밋으로 보존하며 외부 Argon과 직접 연락하지 않았습니다.</p>'''
    (H/'INDEX.html').write_text(html,encoding='utf8');print(json.dumps({'actualFrames':24,'actualPlay':2,'actualRuntimeGeometryOnlyFix':True,'runtimeAllocator':False,'product77DefaultChanged':False,'figure':'WHITE_CARRIER111.png','latestEditor':status['latestEditor']}))
if __name__=='__main__':main()
